1	-- ============================================================
2	-- messages_v1_rpc_tokens — expand enqueue_auto_reply token set
3	-- Adds {{portfolio_link}}, {{aftercare_pdf_link}}, {{artist_name}}
4	-- Strips any unresolved {{...}} tokens defensively.
5	-- ============================================================
6	
7	CREATE OR REPLACE FUNCTION enqueue_auto_reply(
8	  p_conversation_id uuid,
9	  p_rule_id         uuid
10	)
11	RETURNS uuid
12	LANGUAGE plpgsql
13	SECURITY DEFINER
14	SET search_path = public
15	AS $$
16	DECLARE
17	  v_rule            auto_reply_rules%ROWTYPE;
18	  v_template        message_templates%ROWTYPE;
19	  v_conv            conversations%ROWTYPE;
20	  v_studio_name     text := '';
21	  v_client_fname    text := '';
22	  v_booking_link    text := '';
23	  v_portfolio_link  text := '';
24	  v_aftercare_link  text := '';
25	  v_artist_name     text := '';
26	  v_rendered_body   text;
27	  v_channel         text;
28	  v_new_comm_id     uuid;
29	BEGIN
30	  -- Load rule
31	  SELECT * INTO v_rule FROM auto_reply_rules WHERE id = p_rule_id;
32	  IF NOT FOUND OR NOT v_rule.enabled THEN
33	    RETURN NULL;
34	  END IF;
35	
36	  -- Load template
37	  SELECT * INTO v_template FROM message_templates WHERE id = v_rule.template_id;
38	  IF NOT FOUND THEN
39	    RETURN NULL;
40	  END IF;
41	
42	  -- Load conversation
43	  SELECT * INTO v_conv FROM conversations WHERE id = p_conversation_id;
44	  IF NOT FOUND THEN
45	    RETURN NULL;
46	  END IF;
47	
48	  -- Cooldown check: skip if auto-reply was sent within cooldown window
49	  IF v_conv.last_auto_reply_at IS NOT NULL
50	    AND v_conv.last_auto_reply_at > now() - (v_rule.cooldown_minutes * interval '1 minute')
51	  THEN
52	    RETURN NULL;
53	  END IF;
54	
55	  -- Resolve studio tokens
56	  SELECT
57	    COALESCE(s.name, ''),
58	    COALESCE('/book/' || s.slug, '')
59	  INTO v_studio_name, v_booking_link
60	  FROM studios s
61	  WHERE s.id = v_conv.studio_id;
62	
63	  -- Resolve client first name
64	  IF v_conv.client_id IS NOT NULL THEN
65	    SELECT COALESCE(c.first_name, '')
66	    INTO   v_client_fname
67	    FROM   clients c
68	    WHERE  c.id = v_conv.client_id;
69	  END IF;
70	
71	  -- portfolio_link: use studio portfolio page (public URL pattern)
72	  v_portfolio_link := COALESCE('/book/' || (
73	    SELECT s.slug FROM studios s WHERE s.id = v_conv.studio_id
74	  ) || '/portfolio', '');
75	
76	  -- aftercare_pdf_link: use studio aftercare page for now (pdf upload is v2)
77	  v_aftercare_link := COALESCE('/book/' || (
78	    SELECT s.slug FROM studios s WHERE s.id = v_conv.studio_id
79	  ) || '/aftercare', '');
80	
81	  -- artist_name: resolve from conversation's assigned artist (if any)
82	  BEGIN
83	    SELECT COALESCE(p.full_name, '')
84	    INTO   v_artist_name
85	    FROM   conversations c
86	    JOIN   studio_members sm ON sm.studio_id = c.studio_id AND sm.user_id = c.assigned_to
87	    JOIN   profiles p        ON p.id = sm.user_id
88	    WHERE  c.id = p_conversation_id
89	    LIMIT 1;
90	  EXCEPTION WHEN OTHERS THEN
91	    v_artist_name := '';
92	  END;
93	
94	  -- Render template body — replace all known tokens
95	  v_rendered_body := v_template.body;
96	  v_rendered_body := REPLACE(v_rendered_body, '{{studio_name}}',        COALESCE(v_studio_name, ''));
97	  v_rendered_body := REPLACE(v_rendered_body, '{{client_first_name}}',  COALESCE(v_client_fname, ''));
98	  v_rendered_body := REPLACE(v_rendered_body, '{{booking_link}}',       COALESCE(v_booking_link, ''));
99	  v_rendered_body := REPLACE(v_rendered_body, '{{portfolio_link}}',     COALESCE(v_portfolio_link, ''));
100	  v_rendered_body := REPLACE(v_rendered_body, '{{aftercare_pdf_link}}', COALESCE(v_aftercare_link, ''));
101	  v_rendered_body := REPLACE(v_rendered_body, '{{artist_name}}',        COALESCE(v_artist_name, ''));
102	  -- Strip any remaining unresolved tokens
103	  v_rendered_body := REGEXP_REPLACE(v_rendered_body, '\{\{[a-z_]+\}\}', '', 'g');
104	
105	  -- Determine channel
106	  v_channel := CASE
107	    WHEN v_conv.channel = 'voice' THEN 'sms'
108	    WHEN v_conv.channel IN ('sms', 'email') THEN v_conv.channel
109	    ELSE 'sms'
110	  END;
111	
112	  -- Insert outbound queued comm
113	  INSERT INTO client_communications (
114	    studio_id,
115	    client_id,
116	    conversation_id,
117	    channel,
118	    direction,
119	    status,
120	    body,
121	    is_internal_note,
122	    metadata
123	  )
124	  VALUES (
125	    v_conv.studio_id,
126	    v_conv.client_id,
127	    p_conversation_id,
128	    v_channel,
129	    'outbound',
130	    'queued',
131	    v_rendered_body,
132	    false,
133	    jsonb_build_object(
134	      'auto_reply',  true,
135	      'rule_id',     p_rule_id::text,
136	      'template_id', v_rule.template_id::text,
137	      'tone',        v_rule.tone
138	    )
139	  )
140	  RETURNING id INTO v_new_comm_id;
141	
142	  -- Stamp cooldown
143	  UPDATE conversations
144	  SET    last_auto_reply_at = now(),
145	         updated_at         = now()
146	  WHERE  id = p_conversation_id;
147	
148	  RETURN v_new_comm_id;
149	END;
150	$$;
