711	// One-shot: seeds missing default templates. Useful for backfill + Settings UI
712	// "Restore defaults" button.
713	
714	export async function seedDefaultTemplatesAction(): Promise<ActionResult<{ inserted: number }>> {
715	  const authUser = await getAuthenticatedUser()
716	  if (!authUser) return { ok: false, error: 'Unauthorized' }
717	  const gateErr = await requireOmnichannelGate(authUser.studioId)
718	  if (gateErr) return gateErr
719	
720	  try {
721	    const supabase = await createClient()
722	    const { data: member } = await supabase
723	      .from('studio_members')
724	      .select('role')
725	      .eq('studio_id', authUser.studioId)
726	      .eq('user_id', authUser.user.id)
727	      .is('deactivated_at', null)
728	      .single()
729	    if (!member || !['owner', 'admin'].includes(member.role)) {
730	      return { ok: false, error: 'Only owners and admins can restore defaults' }
731	    }
732	    const inserted = await seedDefaultTemplates(authUser.studioId, authUser.user.id, supabase)
733	    revalidateMessages()
734	    return { ok: true, data: { inserted } }
735	  } catch (err) {
736	    logger.error({ err }, 'seedDefaultTemplatesAction: failed')
737	    return { ok: false, error: 'Failed to seed default templates' }
738	  }
739	}
